import{_ as s,o as e,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const k=JSON.parse('{"title":"指标与误差分析","description":"为 Agent 的结果、轨迹、安全、延迟与成本选择可解释指标，并用分层统计和错误分类定位退化原因。","frontmatter":{"title":"指标与误差分析","description":"为 Agent 的结果、轨迹、安全、延迟与成本选择可解释指标，并用分层统计和错误分类定位退化原因。","version":"Python 3.12","verified_at":"2026-07-31","source":["https://platform.openai.com/docs/guides/evals","https://docs.langchain.com/langsmith/evaluation-concepts","https://scikit-learn.org/stable/modules/model_evaluation.html"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/quality/agent-evaluation/metrics-error-analysis.md","filePath":"py-agent/quality/agent-evaluation/metrics-error-analysis.md","lastUpdated":1785589115000}'),t={name:"py-agent/quality/agent-evaluation/metrics-error-analysis.md"};function l(r,a,p,h,o,d){return e(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="指标与误差分析" tabindex="-1">指标与误差分析 <a class="header-anchor" href="#指标与误差分析" aria-label="Permalink to &quot;指标与误差分析&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>一个“总分 83”很少能指导 Agent 改进。它可能掩盖越权调用，也无法说明错误来自检索、规划、工具还是生成。本章按结果、轨迹、运行和风险四类对象选择指标，再用切片和错误分类把数字还原成可行动原因。</p><h2 id="_1-指标的基本模型" tabindex="-1">1. 指标的基本模型 <a class="header-anchor" href="#_1-指标的基本模型" aria-label="Permalink to &quot;1. 指标的基本模型&quot;">​</a></h2><h3 id="_1-1-measurement、metric-与-gate" tabindex="-1">1.1 Measurement、Metric 与 Gate <a class="header-anchor" href="#_1-1-measurement、metric-与-gate" aria-label="Permalink to &quot;1.1 Measurement、Metric 与 Gate&quot;">​</a></h3><ul><li>Measurement：单次运行观察值，如延迟 2.4 秒；</li><li>Metric：按明确规则聚合，如成功率 94%；</li><li>Gate：对指标施加发布判定，如成功率不得低于基线 2 个百分点。</li></ul><p>同一指标可用于趋势观察，不一定适合做硬门禁。样本小或评分噪声高时，直接用单点阈值会造成误判。</p><h3 id="_1-2-单位与方向" tabindex="-1">1.2 单位与方向 <a class="header-anchor" href="#_1-2-单位与方向" aria-label="Permalink to &quot;1.2 单位与方向&quot;">​</a></h3><p>每个指标必须说明单位、取值范围、越大越好还是越小越好、聚合方式和缺失值处理。<code>0.9</code> 可能是 90% 成功率，也可能是平均 1-5 分缩放后的结果，不能只保存数字。</p><h3 id="_1-3-硬约束与优化目标" tabindex="-1">1.3 硬约束与优化目标 <a class="header-anchor" href="#_1-3-硬约束与优化目标" aria-label="Permalink to &quot;1.3 硬约束与优化目标&quot;">​</a></h3><p>安全、授权、数据泄露等指标通常是硬约束；质量、延迟和成本常需要多目标权衡。不要用加权平均让高文风分抵消一次高风险越权。</p><h2 id="_2-结果指标" tabindex="-1">2. 结果指标 <a class="header-anchor" href="#_2-结果指标" aria-label="Permalink to &quot;2. 结果指标&quot;">​</a></h2><h3 id="_2-1-精确匹配与规范化匹配" tabindex="-1">2.1 精确匹配与规范化匹配 <a class="header-anchor" href="#_2-1-精确匹配与规范化匹配" aria-label="Permalink to &quot;2.1 精确匹配与规范化匹配&quot;">​</a></h3><p>适合分类、代码、ID 和结构化提取。比较前可按业务规则规范大小写、空白、日期和集合顺序，但规范化不能抹掉语义错误。</p><h3 id="_2-2-precision、recall-与-f1" tabindex="-1">2.2 Precision、Recall 与 F1 <a class="header-anchor" href="#_2-2-precision、recall-与-f1" aria-label="Permalink to &quot;2.2 Precision、Recall 与 F1&quot;">​</a></h3><p>对实体集合、引用集合或应调用工具集合：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>precision = TP / (TP + FP)</span></span>
<span class="line"><span>recall    = TP / (TP + FN)</span></span>
<span class="line"><span>F1        = 2 * precision * recall / (precision + recall)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>当“多返回错误项”和“漏掉正确项”的成本不同，应分别看 Precision 与 Recall，不要只看 F1。分母为零的策略也必须预先定义。</p><h3 id="_2-3-任务成功率" tabindex="-1">2.3 任务成功率 <a class="header-anchor" href="#_2-3-任务成功率" aria-label="Permalink to &quot;2.3 任务成功率&quot;">​</a></h3><p>以业务终态判定任务是否完成，例如预约确已创建、退款进入正确审批状态。它比文本相似度更贴近用户价值，但需要可靠的环境状态和副作用校验。</p><h3 id="_2-4-rubric-分数" tabindex="-1">2.4 Rubric 分数 <a class="header-anchor" href="#_2-4-rubric-分数" aria-label="Permalink to &quot;2.4 Rubric 分数&quot;">​</a></h3><p>完整性、清晰度和专业性等开放维度可用 1-5 级 Rubric。每一级应有行为锚点，不使用“差、一般、好”这类无法复核的形容词。</p><h2 id="_3-轨迹与工具指标" tabindex="-1">3. 轨迹与工具指标 <a class="header-anchor" href="#_3-轨迹与工具指标" aria-label="Permalink to &quot;3. 轨迹与工具指标&quot;">​</a></h2><h3 id="_3-1-工具选择" tabindex="-1">3.1 工具选择 <a class="header-anchor" href="#_3-1-工具选择" aria-label="Permalink to &quot;3.1 工具选择&quot;">​</a></h3><p>可测工具名称准确率、禁止工具调用率、必要工具召回率和无效调用率。对于多个合法路径，不要把唯一“黄金轨迹”当成绝对正确答案。</p><h3 id="_3-2-参数与权限" tabindex="-1">3.2 参数与权限 <a class="header-anchor" href="#_3-2-参数与权限" aria-label="Permalink to &quot;3.2 参数与权限&quot;">​</a></h3><p>参数指标包括 Schema 合法率、关键字段准确率、可信上下文覆盖率和越权参数率。权限失败应单独统计，不能混入普通工具失败。</p><h3 id="_3-3-路径与效率" tabindex="-1">3.3 路径与效率 <a class="header-anchor" href="#_3-3-路径与效率" aria-label="Permalink to &quot;3.3 路径与效率&quot;">​</a></h3><p>观察模型调用次数、工具调用次数、循环次数、重试次数和无进展步骤。更短不一定更好：减少必要的验证步骤可能提高风险。效率指标必须与成功和安全共同解释。</p><h3 id="_3-4-状态一致性" tabindex="-1">3.4 状态一致性 <a class="header-anchor" href="#_3-4-状态一致性" aria-label="Permalink to &quot;3.4 状态一致性&quot;">​</a></h3><p>对工作流检查必经状态、非法迁移、终止原因、Checkpoint 恢复一致性和副作用重复。Trace 是计算这些指标的证据，而非分数本身。</p><h2 id="_4-rag-与生成指标的边界" tabindex="-1">4. RAG 与生成指标的边界 <a class="header-anchor" href="#_4-rag-与生成指标的边界" aria-label="Permalink to &quot;4. RAG 与生成指标的边界&quot;">​</a></h2><h3 id="_4-1-检索阶段" tabindex="-1">4.1 检索阶段 <a class="header-anchor" href="#_4-1-检索阶段" aria-label="Permalink to &quot;4.1 检索阶段&quot;">​</a></h3><p>常用 Recall@k、Precision@k、MRR 和 nDCG。它们需要相关性标签，回答“正确证据有没有被找回、排序是否靠前”，不能直接证明最终答案忠实。</p><h3 id="_4-2-生成阶段" tabindex="-1">4.2 生成阶段 <a class="header-anchor" href="#_4-2-生成阶段" aria-label="Permalink to &quot;4.2 生成阶段&quot;">​</a></h3><p>正确性衡量答案与事实，忠实性衡量断言是否由所给上下文支持，引用准确性衡量引用是否真正支持对应陈述，引用完整性衡量需要来源的陈述是否都有引用。</p><p>这些指标在 RAG 模块中展开。本模块只强调：阶段指标用于定位，端到端任务成功用于验收。</p><h2 id="_5-运行指标" tabindex="-1">5. 运行指标 <a class="header-anchor" href="#_5-运行指标" aria-label="Permalink to &quot;5. 运行指标&quot;">​</a></h2><h3 id="_5-1-延迟" tabindex="-1">5.1 延迟 <a class="header-anchor" href="#_5-1-延迟" aria-label="Permalink to &quot;5.1 延迟&quot;">​</a></h3><p>至少记录首 Token 时间、总时长、各模型/工具 Span 时长和队列等待。报告 p50、p95、p99 与样本数；平均值会掩盖长尾。</p><h3 id="_5-2-成本与用量" tabindex="-1">5.2 成本与用量 <a class="header-anchor" href="#_5-2-成本与用量" aria-label="Permalink to &quot;5.2 成本与用量&quot;">​</a></h3><p>统计每成功任务成本，而不只是每请求 Token。失败重试、无效工具和超时调用都会消耗资源却不产生结果。价格会变化，因此保存原始用量与计价版本。</p><h3 id="_5-3-可靠性" tabindex="-1">5.3 可靠性 <a class="header-anchor" href="#_5-3-可靠性" aria-label="Permalink to &quot;5.3 可靠性&quot;">​</a></h3><p>记录成功率、错误类别、重试后成功率、取消率、降级率和恢复时间。把所有异常合并成“失败率”会让限流、用户取消和程序错误无法区分。</p><h2 id="_6-聚合与统计不确定性" tabindex="-1">6. 聚合与统计不确定性 <a class="header-anchor" href="#_6-聚合与统计不确定性" aria-label="Permalink to &quot;6. 聚合与统计不确定性&quot;">​</a></h2><h3 id="_6-1-micro、macro-与-slice" tabindex="-1">6.1 Micro、Macro 与 Slice <a class="header-anchor" href="#_6-1-micro、macro-与-slice" aria-label="Permalink to &quot;6.1 Micro、Macro 与 Slice&quot;">​</a></h3><p>Micro 聚合让高频类别占更大权重；Macro 先对每类求均值，更能暴露低频类别退化。两者都应配合关键 Slice 报告。</p><h3 id="_6-2-分布而非单点" tabindex="-1">6.2 分布而非单点 <a class="header-anchor" href="#_6-2-分布而非单点" aria-label="Permalink to &quot;6.2 分布而非单点&quot;">​</a></h3><p>同时报告样本数、均值或比例、分位数和置信区间。10 个样本的 90% 与 1000 个样本的 90% 证据强度不同。</p><h3 id="_6-3-配对比较" tabindex="-1">6.3 配对比较 <a class="header-anchor" href="#_6-3-配对比较" aria-label="Permalink to &quot;6.3 配对比较&quot;">​</a></h3><p>候选版本和基线应运行同一批样本，并比较每个样本的差值。配对设计能减少样本难度差异带来的噪声。</p><div class="language-python vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> statistics </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mean</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> paired_delta</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    baseline: dict[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    candidate: dict[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> baseline.keys() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> candidate.keys():</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        raise</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ValueError</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;runs must contain identical case ids&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mean(candidate[key] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> baseline[key] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> baseline)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>这段代码只计算平均配对差，不提供显著性结论。正式实验还应使用适合指标分布的置信区间或统计检验。</p><h2 id="_7-错误分类" tabindex="-1">7. 错误分类 <a class="header-anchor" href="#_7-错误分类" aria-label="Permalink to &quot;7. 错误分类&quot;">​</a></h2><h3 id="_7-1-按结果阶段分类" tabindex="-1">7.1 按结果阶段分类 <a class="header-anchor" href="#_7-1-按结果阶段分类" aria-label="Permalink to &quot;7.1 按结果阶段分类&quot;">​</a></h3><p>一个实用分类树：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入理解</span></span>
<span class="line"><span>  - 意图/实体错误</span></span>
<span class="line"><span>上下文</span></span>
<span class="line"><span>  - 检索遗漏/错误记忆/上下文截断</span></span>
<span class="line"><span>决策</span></span>
<span class="line"><span>  - 错误工具/错误路由/未停止</span></span>
<span class="line"><span>执行</span></span>
<span class="line"><span>  - 参数/权限/超时/副作用重复</span></span>
<span class="line"><span>生成</span></span>
<span class="line"><span>  - 事实/忠实性/格式/引用错误</span></span>
<span class="line"><span>系统</span></span>
<span class="line"><span>  - 配置/依赖/容量/版本错误</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>主因与伴随因素分开记录，避免一个样本重复计入多个一级类别后无法解释总量。</p><h3 id="_7-2-严重度与可发现性" tabindex="-1">7.2 严重度与可发现性 <a class="header-anchor" href="#_7-2-严重度与可发现性" aria-label="Permalink to &quot;7.2 严重度与可发现性&quot;">​</a></h3><p>错误还应标记用户影响、发生频率和是否能由现有检测发现。低频但不可逆的写操作越权，优先级可能高于高频的轻微文风问题。</p><h3 id="_7-3-归因证据" tabindex="-1">7.3 归因证据 <a class="header-anchor" href="#_7-3-归因证据" aria-label="Permalink to &quot;7.3 归因证据&quot;">​</a></h3><p>错误标签要附输入、输出、相关 Trace、工具结果、模型与配置版本。只看最终答案容易把检索遗漏误判为模型幻觉。</p><h2 id="_8-从误差到改进" tabindex="-1">8. 从误差到改进 <a class="header-anchor" href="#_8-从误差到改进" aria-label="Permalink to &quot;8. 从误差到改进&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误模式</th><th>优先检查</th><th>可能改进</th></tr></thead><tbody><tr><td>证据未召回</td><td>查询、切分、过滤、索引</td><td>检索配置或数据</td></tr><tr><td>证据存在但答错</td><td>上下文组装、指令、模型</td><td>Prompt 或模型</td></tr><tr><td>工具参数错误</td><td>Schema 描述、示例、校验</td><td>契约和纠错</td></tr><tr><td>重复调用</td><td>停止条件、状态、重试</td><td>控制流与幂等</td></tr><tr><td>只在长输入失败</td><td>截断、位置、上下文预算</td><td>内容选择策略</td></tr></tbody></table><p>先修复占比高、损失大且原因明确的错误簇，再运行同一回归集。只针对单个样本补提示词，容易造成过拟合。</p><h2 id="_9-常见误用" tabindex="-1">9. 常见误用 <a class="header-anchor" href="#_9-常见误用" aria-label="Permalink to &quot;9. 常见误用&quot;">​</a></h2><ol><li><strong>只看总平均</strong>：关键语言或高风险任务可能已经崩溃。</li><li><strong>把文本相似度当事实正确性</strong>：措辞相似不等于结论正确。</li><li><strong>把 Judge 分数当客观真值</strong>：评分器也有偏差和方差。</li><li><strong>用效率指标单独优化</strong>：少一次工具调用可能意味着漏掉必要验证。</li><li><strong>指标变了但定义没版本化</strong>：历史曲线失去可比性。</li></ol><h2 id="_10-指标卡检查表" tabindex="-1">10. 指标卡检查表 <a class="header-anchor" href="#_10-指标卡检查表" aria-label="Permalink to &quot;10. 指标卡检查表&quot;">​</a></h2><p>每个指标都应回答：测量对象是什么，评分函数和单位是什么，方向是什么，在哪些样本上计算，如何聚合，缺失值如何处理，阈值依据是什么，谁负责调查失败。只有能连接到错误分类和改进行动的指标，才真正进入质量闭环。</p>`,69)])])}const b=s(t,[["render",l]]);export{k as __pageData,b as default};
